import { Component } from '@angular/core';

interface Task {
  id: number;
  title: string;
  done: boolean;
}

@Component({
  selector: 'app-task-list',
  template: `
    <ul>
      <li *ngFor="let task of tasks">
        <input type="checkbox" [checked]="task.done" />
        {{ task.title }}
      </li>
    </ul>
  `
})
export class TaskListComponent {
  tasks: Task[] = [
    { id: 1, title: 'Write plan', done: true },
    { id: 2, title: 'Ship feature', done: false }
  ];

  addTask(title: string): void {
    // No trackBy: Angular diffs by object identity, so any
    // array replacement re-creates every DOM row and loses
    // the checkbox state of untouched items.
    this.tasks = [
      ...this.tasks,
      { id: this.tasks.length + 1, title, done: false }
    ];
  }
}

import { Component } from '@angular/core';

interface Task {
  id: number;
  title: string;
  done: boolean;
}

@Component({
  selector: 'app-task-list',
  template: `
    <ul>
      @for (task of tasks; track task.id) {
        <li>
          <input type="checkbox" [checked]="task.done" />
          {{ task.title }}
        </li>
      } @empty {
        <li>No tasks yet.</li>
      }
    </ul>
  `
})
export class TaskListComponent {
  tasks: Task[] = [
    { id: 1, title: 'Write plan', done: true },
    { id: 2, title: 'Ship feature', done: false }
  ];

  addTask(title: string): void {
    // Stable track by id: Angular reuses DOM rows whose keys
    // still exist and only inserts one new row.
    this.tasks = [
      ...this.tasks,
      { id: this.tasks.length + 1, title, done: false }
    ];
  }
}
